for name,before,after,edits in CHANGES:
    path=Path(name);raw=path.read_bytes()
    git_hash=lambda data:hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
    if git_hash(raw)!=before:raise ValueError('Concurrent source edit: '+name)
    lines=raw.decode().splitlines(keepends=True)
    for start,end,replacement in reversed(edits):lines[start:end]=replacement.splitlines(keepends=True)
    result=''.join(lines).encode()
    if git_hash(result)!=after:raise ValueError('Integration content mismatch: '+name)
    path.write_bytes(result)
    print(name,after)
